ValidationRule.errorConditionFormula:
OR($RecordType.Id = "012000000000j1H",($RecordType.Id = "012000000000g0D" &&  ISPICKVAL(Origin,"Credit Check Button")))  &&  
Contact.Account_18_Digit_ID__c  <> "001000000034Nt8AAE" &&
/*Rithum account id*/ 
Contact.Account_18_Digit_ID__c  <> "0012A00002S3drbQAB" &&
/*Rithum_Archive account id*/
Contact.Account_18_Digit_ID__c  <> "001F000000ku5TSIAY" &&
/*Commerce Technologies, LLC dba CommerceHub account id*/
$Profile.Name <> "SystemAccess" && 
NOT(ISPICKVAL(Origin,"Email-Data Privacy or GDPR"))
